"""Suggest supplier orders from weekly inventory counts and par levels."""
import math

def suggest_orders(items):
    """items: list of dicts with name, on_hand, par, pack_size, unit_cost."""
    orders = []
    for it in items:
        short = it["par"] - it["on_hand"]
        if short <= 0:
            continue
        packs = math.ceil(short / it["pack_size"])
        orders.append({
            "item": it["name"],
            "packs": packs,
            "cost": round(packs * it["pack_size"] * it["unit_cost"], 2),
        })
    return orders

if __name__ == "__main__":
    demo = [
        {"name": "Chicken thigh (lb)", "on_hand": 12, "par": 30, "pack_size": 10, "unit_cost": 2.10},
        {"name": "Rice (lb)", "on_hand": 40, "par": 50, "pack_size": 25, "unit_cost": 0.80},
    ]
    for o in suggest_orders(demo):
        print(o)
EOF
